data.worker.py:
"""HTTP-only qualification worker: ONE process per allocated accelerator unit, hosting every requested stage.

Runs inside an owned Pod (no exec/logs needed: all evidence is returned over HTTP). Stages execute sequentially
under one lock so a single allocated GPU/NPU unit is never shared by concurrent model calls.

  GET  /ready   200 once loading finished (success or failure), so load errors stay readable over HTTP
  GET  /health  {status, node, pod_uid, stages: {stage: describe() | load error}}
  POST /run     {run_id, request_id, stage, data(bytes, binary framing) | inputs{vision,speech}(base64)}
                -> {status, data(base64), receipt}; errors -> HTTP 4xx/5xx with {status:error, error, stage}
Load failures are never replaced by another backend: the stage stays failed and /run answers 503.
Protocol framing reuses the frozen real-topology-live/http_runtime.py helpers (unchanged copy).
"""
import argparse
import base64
import hashlib
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import json
import os
import socket
from pathlib import Path
import sys
import threading
import time
import traceback

sys.path.insert(0, str(Path(__file__).resolve().parent))
import stages  # noqa: E402
from http_runtime import decode_body, payload  # noqa: E402


def digest(data):
    return hashlib.sha256(data).hexdigest()


class Worker:
    def __init__(self, backend, stage_names, model_root=None, source_root=None, onnx=None, onnx_sha256=None, loader=None):
        self.backend, self.lock, self.sequence = backend, threading.Lock(), 0
        # Visible device queue (additive): callers waiting for / holding the one-unit device lock.
        self.queue_lock, self.waiting, self.active = threading.Lock(), 0, 0
        # Identity is fixed per process (the Pod's downward-API env at start), never re-read per request.
        self.node, self.pod_uid = os.environ.get('NODE_NAME'), os.environ.get('POD_UID')
        self.stages, self.errors, self.descriptions = {}, {}, {}
        loader = loader or stages.load
        for name in stage_names:
            try:
                stage = loader(name, backend, model_root=model_root, source_root=source_root, onnx_path=onnx, expected_onnx_sha256=onnx_sha256)
                self.stages[name], self.descriptions[name] = stage, stage.describe()
                if self.descriptions[name].get('backend') != backend:
                    raise stages.DeviceMismatch(f'{name} loaded as {self.descriptions[name].get("backend")}, requested {backend}')
            except Exception as error:
                self.stages.pop(name, None)
                self.errors[name] = dict(type=type(error).__name__, error=repr(error)[:1000],
                                         status='dependency_unavailable' if isinstance(error, stages.BackendUnavailable) else 'load_failed',
                                         traceback=traceback.format_exc()[-2000:])
        self.loaded = True

    def health(self):
        return dict(status='ready' if not self.errors else ('partial' if self.stages else 'failed'), backend=self.backend,
                    node=self.node, pod_uid=self.pod_uid, stages=self.descriptions, errors=self.errors,
                    queue=dict(waiting=self.waiting, active=self.active, completed=self.sequence))

    def run(self, body):
        # Optional bounded admission (additive, quality-network-baselines DAG mode): one absolute local monotonic expiry,
        # fixed before input preparation (decode/hash), bounds the lock wait and is rechecked once the lock is held, so an
        # expired request is answered without a model call. Neither field -> unbounded wait (qualification path).
        expires = body.get('deadline_monotonic')
        if expires is None and body.get('queue_deadline_s') is not None:
            expires = time.monotonic() + max(0.0, float(body['queue_deadline_s']))
        name = body.get('stage')
        if name in self.errors:
            return 503, dict(status='error', stage=name, error='stage not loaded', load_error=self.errors[name])
        if name not in self.stages:
            return 400, dict(status='error', stage=name, error='stage not hosted by this worker')
        tensor = body.get('input') == 'tensor'
        if tensor and not hasattr(self.stages[name], 'run_tensor'):
            return 400, dict(status='error', stage=name, error='stage has no tensor-input form on this backend')
        if name == 'fusion':
            data = {k: base64.b64decode(body['inputs'][k], validate=True) for k in ('vision', 'speech')}
            input_sha = {k: digest(v) for k, v in data.items()}
        else:
            data = payload(body['data'])
            input_sha = digest(data)
        queued = time.perf_counter()
        with self.queue_lock:
            depth_at_arrival = dict(waiting=self.waiting, active=self.active)
            self.waiting += 1
        try:
            if expires is None:
                acquired = self.lock.acquire()
            else:
                acquired = time.monotonic() < expires and self.lock.acquire(timeout=max(0.0, expires - time.monotonic()))
                if acquired and time.monotonic() >= expires:
                    self.lock.release()
                    acquired = False
        finally:
            with self.queue_lock:
                self.waiting -= 1
        if not acquired:
            return 504, dict(status='error', stage=name, error='queue_deadline_expired', request_id=body.get('request_id'),
                             queue_wait_ms=(time.perf_counter() - queued) * 1000, queue_at_arrival=depth_at_arrival)
        with self.queue_lock:
            self.active += 1
        try:
            self.sequence += 1
            sequence = self.sequence
            started = time.perf_counter()
            queue_wait_ms = (started - queued) * 1000
            try:
                output, timing = (self.stages[name].run_tensor if tensor else self.stages[name].run)(data)
            except Exception as error:  # structured: which phase failed (e.g. request-time NPU compile vs inference)
                return 500, dict(status='error', stage=name, phase=getattr(error, 'phase', 'inference'), type=type(error).__name__,
                                 error=repr(getattr(error, 'original', error))[:1500], request_id=body.get('request_id'), sequence=sequence,
                                 queue_wait_ms=queue_wait_ms)
            wall = (time.perf_counter() - started) * 1000
        finally:
            with self.queue_lock:
                self.active -= 1
            self.lock.release()
        description = self.descriptions[name]
        if timing.get('output_device') and not timing['output_device'].startswith(description['device'].split(':')[0]):
            raise stages.DeviceMismatch(f'{name} produced output on {timing["output_device"]}, worker device {description["device"]}')
        receipt = dict(stage=name, backend=self.backend, device=description['device'], node=self.node,
                       pod_uid=self.pod_uid, run_id=body.get('run_id'), request_id=body.get('request_id'),
                       sequence=sequence, input_sha256=input_sha, output_sha256=digest(output), output_bytes=len(output),
                       model_sha256=description.get('model_sha256'), derived_artifact_sha256=description.get('derived_artifact_sha256'),
                       worker_wall_ms=wall, timing=timing, static=description,
                       input_kind='tensor' if tensor else 'raw', queue_wait_ms=queue_wait_ms, queue_at_arrival=depth_at_arrival)
        return 200, dict(status='ok', data=base64.b64encode(output).decode(), receipt=receipt)


def serve(worker, host='0.0.0.0', port=8080, max_active=2, body_timeout_s=30.0, max_body=32 * 1024 * 1024, read_deadline_s=None):
    """Bounded HTTP admission: at most `max_active` connections are handled (each slot is taken before any byte of
    the request is read; excess connections get an immediate structured 503 and are closed), every socket read has a
    `body_timeout_s` inactivity timeout AND an absolute `read_deadline_s` for request line + headers + body (a timer
    shuts the socket if reading is not finished in time, so trickling clients cannot hold a slot), bodies above
    `max_body` are refused with 413 before reading, and the slot is released
    on every path (success, error, timeout, disconnect). Model calls stay serialized by Worker.lock, so at most
    `max_active` decoded payloads exist at once. Qualification infrastructure only, not an admission-control study."""
    absolute = read_deadline_s if read_deadline_s is not None else 2 * body_timeout_s

    class Handler(BaseHTTPRequestHandler):
        timeout = body_timeout_s  # StreamRequestHandler sets this as the socket timeout before reading the request

        def setup(self):
            super().setup()
            self.read_done = threading.Event()
            self.read_timer = threading.Timer(absolute, self._expire)
            self.read_timer.daemon = True
            self.read_timer.start()

        def _expire(self):
            if not self.read_done.is_set():
                try:
                    self.connection.shutdown(socket.SHUT_RDWR)
                except OSError:
                    pass

        def _reading_finished(self):
            self.read_done.set()
            self.read_timer.cancel()

        def finish(self):
            self.read_timer.cancel()
            try:
                super().finish()
            except OSError:
                pass

        def _send(self, status, value):
            raw = json.dumps(value, separators=(',', ':'), default=str).encode()
            self.send_response(status)
            self.send_header('Content-Type', 'application/json')
            self.send_header('Content-Length', str(len(raw)))
            self.send_header('Connection', 'close')
            self.end_headers()
            self.wfile.write(raw)

        def do_GET(self):
            self._reading_finished()
            if self.path == '/ready':
                self._send(200 if worker.loaded else 503, dict(loaded=worker.loaded))
            elif self.path == '/health':
                self._send(200, worker.health())
            else:
                self._send(404, dict(status='error', error='unknown path'))

        def do_POST(self):
            if self.path != '/run':
                self._send(404, dict(status='error', error='unknown path'))
                return
            try:
                size = int(self.headers.get('Content-Length', 0))
                if size < 1:
                    raise ValueError('Invalid body size')
                if size > max_body:
                    self._reading_finished()
                    self._send(413, dict(status='error', error='body too large', limit=max_body))
                    return
                raw = self.rfile.read(size)
                self._reading_finished()
                if len(raw) != size:
                    return  # socket shut by the absolute read deadline or the client went away
                body = decode_body(raw, self.headers.get('Content-Type'))
                status, value = worker.run(body)
            except (ValueError, KeyError, TypeError) as error:
                status, value = 400, dict(status='error', error=repr(error)[:1000])
            except OSError:
                return  # read deadline / disconnect: nothing can be answered; slot is released by the server
            except Exception as error:
                status, value = 500, dict(status='error', error=repr(error)[:1000], type=type(error).__name__)
            self._send(status, value)

        def log_message(self, *args):
            pass

    class BoundedServer(ThreadingHTTPServer):
        daemon_threads = True
        slots = threading.BoundedSemaphore(max_active)
        held = [0]
        lock = threading.Lock()

        def active_slots(self):
            with self.lock:
                return self.held[0]

        def process_request(self, request, client_address):
            if not self.slots.acquire(blocking=False):
                raw = json.dumps(dict(status='error', error='worker at admission capacity', max_active=max_active)).encode()
                try:
                    request.sendall(b'HTTP/1.1 503 Service Unavailable\r\nContent-Type: application/json\r\nConnection: close\r\n'
                                    b'Content-Length: ' + str(len(raw)).encode() + b'\r\n\r\n' + raw)
                except OSError:
                    pass
                self.shutdown_request(request)
                return
            with self.lock:
                self.held[0] += 1
            try:
                super().process_request(request, client_address)
            except BaseException:
                self._release()
                raise

        def process_request_thread(self, request, client_address):
            try:
                super().process_request_thread(request, client_address)
            finally:
                self._release()

        def _release(self):
            with self.lock:
                self.held[0] -= 1
            self.slots.release()
    return BoundedServer((host, port), Handler)


def main(argv=None):
    ap = argparse.ArgumentParser(description='HTTP-only multi-stage qualification worker (one per accelerator unit).')
    ap.add_argument('--backend', required=True, choices=stages.BACKENDS)
    ap.add_argument('--stages', required=True, help='comma list of vision,speech,fusion')
    ap.add_argument('--onnx', default=None)
    ap.add_argument('--onnx-sha256', default=None)
    ap.add_argument('--port', type=int, default=8080)
    args = ap.parse_args(argv)
    names = [s for s in args.stages.split(',') if s]
    if any(s not in stages.STAGES for s in names):
        ap.error('unknown stage')
    class Pending:
        loaded, backend = False, args.backend

        def health(self):
            return dict(status='loading', backend=args.backend, node=os.environ.get('NODE_NAME'), pod_uid=os.environ.get('POD_UID'))

        def run(self, body):
            return 503, dict(status='error', error='loading')
    proxy = Pending()
    server = serve(proxy, port=args.port)
    threading.Thread(target=server.serve_forever, daemon=True).start()
    worker = Worker(args.backend, names, onnx=args.onnx, onnx_sha256=args.onnx_sha256)
    # The handler is bound to `proxy`; swap in the loaded worker's methods (readiness flips only after loading).
    proxy.health, proxy.run, proxy.loaded = worker.health, worker.run, True
    print(json.dumps(dict(event='worker_loaded', **{k: v for k, v in worker.health().items() if k != 'stages'})), flush=True)
    threading.Event().wait()


if __name__ == '__main__':
    main()

data.dag_worker.py:
"""DAG-mode worker for the baseline-first comparison: the qualification Worker plus real stage-to-stage forwarding.

Shipped next to the qualification worker.py/stages.py (unchanged model code) and selected by bootstrap.py with
WORKER_MODULE=dag_worker. One process per allocated device unit; every model call still takes the Worker's one-unit
lock, so stages co-hosted on one device (e.g. vision + speech on one Jetson GPU) queue for it; the queue is visible in
/health and in every receipt (queue_wait_ms, queue_at_arrival).

POST /run with mode='dag':
  {mode:'dag', run_id, request_id, stage, input:'raw'|'tensor', data(bytes), forward:[hop,...], budget_s}
  The stage runs; its output is POSTed (binary framing) to forward[0]['url'] with forward[1:]; the reply carries this
  worker's receipt plus every downstream receipt and hop record. Data really travels worker -> next worker on the
  route the generator wrote into the hop (direct Pod IP or the shared gateway); nothing returns to the origin in between.
  stage='fusion_join', part='vision'|'speech': fan-in. The two branch chains of one request meet here; the second part
  to arrive runs fusion (one lock acquisition) and both waiting callers get the same fusion result. A part whose partner
  does not arrive within its budget answers join_timeout (no fusion, no substitute).
POST /run mode='queue' -> {waiting, active, completed, joins_open, inflight, dag_requests, node, pod_uid}: light observation
  (poller); inflight counts admitted dag/probe/sink requests until their reply, so forwarding and join waits are visible.
POST /run mode='sink' {data} -> {bytes, sha256}: payload sink for transfer probes.
POST /run mode='probe' {url, bytes, reps, timeout_s} -> this worker POSTs `bytes` random payload to url (a sink) reps times and
  returns the measured application round-trip times (route profiling from this worker's own network position).
Hop timing: rpc_ms is the sender's wall time of the downstream POST; it CONTAINS the downstream work, so it is never
added to anything; the generator measures end-to-end latency on its own clock only.
"""
import base64
import hashlib
import json
import os
from pathlib import Path
import sys
import threading
import time
import urllib.error

sys.path.insert(0, str(Path(__file__).resolve().parent))
import worker as base  # noqa: E402
from bounded_http import post as bounded_post  # noqa: E402
from http_runtime import payload  # noqa: E402

Worker = None  # bound below
MAX_ACTIVE = int(os.environ.get('DAG_MAX_ACTIVE', '96'))
MAX_JOINS = 256
# Nested budgets shrink by this margin per hop so an inner timeout (e.g. join_timeout) is answered before the caller's
# own socket timeout fires; the caller then records the explicit cause instead of a bare timeout.
FORWARD_MARGIN_S = 0.1


def digest(data):
    return hashlib.sha256(data).hexdigest()


def slim(receipt):
    """DAG receipts drop the static load description (kept in /health) for its hash, so per-request evidence travelling
    back along the chain stays small; identity, hashes, device and timing fields are kept."""
    out = dict(receipt)
    static = out.pop('static', None)
    out['static_sha256'] = digest(json.dumps(static, sort_keys=True, default=str).encode()) if static is not None else None
    return out


class DagWorker(base.Worker):
    def __init__(self, *args, post=None, **kwargs):
        super().__init__(*args, **kwargs)
        self.post = post or bounded_post  # absolute per-forward deadline (not a socket inactivity timeout)
        self.joins, self.join_lock = {}, threading.Lock()
        self.counters = dict(dag_requests=0, forwarded=0, forward_errors=0, join_timeouts=0, joins_completed=0, rejected_joins=0)
        # Admitted dag/probe/sink requests from arrival to reply, including compute, forwarding and join waits (drain).
        self.inflight = 0

    def health(self):
        out = super().health()
        with self.join_lock:
            out['joins_open'] = len(self.joins)
            out['dag_counters'] = dict(self.counters)
        return out

    def run(self, body):
        if body.get('mode') == 'queue':
            with self.join_lock:
                joins, inflight, requests = len(self.joins), self.inflight, self.counters['dag_requests']
            return 200, dict(status='ok', waiting=self.waiting, active=self.active, completed=self.sequence, joins_open=joins,
                             inflight=inflight, dag_requests=requests, node=self.node, pod_uid=self.pod_uid)
        if body.get('mode') not in ('sink', 'probe', 'dag'):
            return super().run(body)
        with self.join_lock:
            self.inflight += 1
        try:
            return self._run(body)
        finally:
            with self.join_lock:
                self.inflight -= 1

    def _run(self, body):
        if body.get('mode') == 'sink':
            data = payload(body['data'])
            return 200, dict(status='ok', bytes=len(data), sha256=digest(data))
        if body.get('mode') == 'probe':
            return self.probe(body)
        with self.join_lock:
            self.counters['dag_requests'] += 1
        started = time.monotonic()
        budget = float(body.get('budget_s') or 30)
        if body.get('stage') == 'fusion_join':
            return self.join(body, started, budget)
        stage_body = {k: v for k, v in body.items() if k not in ('mode', 'forward', 'budget_s')}
        stage_body['deadline_monotonic'] = started + budget - FORWARD_MARGIN_S  # absolute: covers decode, hashing and the lock
        status, reply = super().run(stage_body)
        if status != 200:
            return status, dict(reply, receipts=[], hops=[])
        receipts, hops = [slim(reply['receipt'])], []
        forward = body.get('forward') or []
        if not forward:
            return 200, dict(status='ok', data=reply['data'], receipts=receipts, hops=hops)
        hop, rest = forward[0], forward[1:]
        out = base64.b64decode(reply['data'])
        remaining = budget - (time.monotonic() - started) - FORWARD_MARGIN_S
        if remaining <= 0.05:
            return 504, dict(status='error', error='budget exhausted before forward', stage=body['stage'], receipts=receipts, hops=hops)
        nbody = dict(mode='dag', run_id=body.get('run_id'), request_id=body.get('request_id'), stage=hop['stage'],
                     input=hop.get('input', 'raw'), forward=rest, budget_s=remaining, data=out,
                     **({'part': hop['part']} if 'part' in hop else {}))
        sent = time.monotonic()
        record = dict(src=hop.get('src'), dst=hop.get('dst'), route=hop.get('route'), stage=hop['stage'], payload_bytes=len(out),
                      output_sha256=digest(out))
        try:
            downstream = self.post(hop['url'], nbody, timeout=remaining + FORWARD_MARGIN_S / 2)
            record.update(rpc_ms=(time.monotonic()-sent)*1000, status=downstream.get('status'))
        except urllib.error.HTTPError as error:
            text = error.read(4000).decode(errors='replace')
            try:
                downstream = json.loads(text)
            except ValueError:
                downstream = dict(status='error', error=text[:500])
            record.update(rpc_ms=(time.monotonic()-sent)*1000, status='http_error', code=error.code)
            with self.join_lock:
                self.counters['forward_errors'] += 1
            return error.code, dict(status='error', error=downstream.get('error'), failed_stage=downstream.get('failed_stage', hop['stage']),
                                    receipts=receipts+downstream.get('receipts', []), hops=[record]+downstream.get('hops', []))
        except Exception as error:
            timed_out = 'timed out' in repr(error).lower() or isinstance(error, TimeoutError)
            record.update(rpc_ms=(time.monotonic()-sent)*1000, status='forward_timeout' if timed_out else 'transport_error', error=repr(error)[:300])
            with self.join_lock:
                self.counters['forward_errors'] += 1
            return (504 if timed_out else 502), dict(status='error', error='forward_timeout' if timed_out else repr(error)[:300],
                                                     failed_stage=hop['stage'], receipts=receipts, hops=[record])
        with self.join_lock:
            self.counters['forwarded'] += 1
        return 200, dict(status='ok', data=downstream.get('data'), receipts=receipts+downstream.get('receipts', []),
                         hops=[record]+downstream.get('hops', []), join=downstream.get('join'))

    def join(self, body, started, budget):
        part, key = body.get('part'), (body.get('run_id'), body.get('request_id'))
        if part not in ('vision', 'speech'):
            return 400, dict(status='error', error='fusion_join part must be vision or speech', receipts=[], hops=[])
        data = payload(body['data'])
        with self.join_lock:
            entry = self.joins.get(key)
            if entry is None:
                if len(self.joins) >= MAX_JOINS:
                    self.counters['rejected_joins'] += 1
                    return 503, dict(status='error', error='join table full', receipts=[], hops=[])
                entry = self.joins[key] = dict(parts={}, event=threading.Event(), result=None, opened=time.monotonic())
            if part in entry['parts']:
                return 409, dict(status='error', error=f'duplicate {part} part', receipts=[], hops=[])
            entry['parts'][part] = data
            complete = len(entry['parts']) == 2
        if not complete:
            remaining = budget - (time.monotonic() - started) - FORWARD_MARGIN_S
            if not entry['event'].wait(max(0.0, remaining)):
                with self.join_lock:
                    if self.joins.get(key) is entry and entry['result'] is None:
                        del self.joins[key]
                        self.counters['join_timeouts'] += 1
                        return 504, dict(status='error', error='join_timeout', failed_stage='fusion', missing=[p for p in ('vision', 'speech')
                                                                                                             if p not in entry['parts']],
                                         receipts=[], hops=[])
                entry['event'].wait()  # the partner already started fusion; its result is about to be set
            status, reply = entry['result']
            return status, dict(reply, join=dict(role='first', waited_ms=(time.monotonic()-started)*1000))
        fusion = dict(run_id=body.get('run_id'), request_id=body.get('request_id'), stage='fusion',
                      inputs={k: base64.b64encode(v).decode() for k, v in entry['parts'].items()},
                      deadline_monotonic=started + budget - FORWARD_MARGIN_S)
        try:
            status, reply = base.Worker.run(self, fusion)
        except Exception as error:
            status, reply = 500, dict(status='error', error=repr(error)[:500])
        result = (status, dict(status=reply.get('status'), data=reply.get('data'), error=reply.get('error'),
                               receipts=[slim(reply['receipt'])] if 'receipt' in reply else [], hops=[],
                               **({'failed_stage': 'fusion'} if status != 200 else {})))
        with self.join_lock:
            entry['result'] = result
            self.joins.pop(key, None)
            self.counters['joins_completed'] += 1
        entry['event'].set()
        return result[0], dict(result[1], join=dict(role='second', waited_ms=0.0))

    def probe(self, body):
        size, reps = int(body.get('bytes', 1024)), int(body.get('reps', 3))
        if not 1 <= size <= 8 * 1024 * 1024 or not 1 <= reps <= 10:
            return 400, dict(status='error', error='probe bytes/reps out of range')
        data, rows = os.urandom(size), []
        for _ in range(reps):
            sent = time.monotonic()
            try:
                reply = self.post(body['url'], dict(mode='sink', run_id=body.get('run_id'), request_id='probe', data=data),
                                  timeout=float(body.get('timeout_s', 60)))
                ok = reply.get('sha256') == digest(data) and reply.get('bytes') == size
                rows.append(dict(rtt_ms=(time.monotonic()-sent)*1000, ok=ok))
            except Exception as error:
                rows.append(dict(rtt_ms=(time.monotonic()-sent)*1000, ok=False, error=repr(error)[:200]))
        return 200, dict(status='ok', bytes=size, rows=rows, node=self.node, pod_uid=self.pod_uid)


Worker = DagWorker


def serve(worker, host='0.0.0.0', port=8080, **kwargs):
    """Qualification serve() with a DAG connection admission cap. Chains are nested synchronous RPCs: a forwarding stage
    and a waiting join part each keep their connection open (without holding the device lock), so one request can hold
    up to 3 connections per branch on a worker hosting several of its tasks. The cap is therefore a connection limit,
    much larger than the one-unit device cap; overflow answers 503 and is recorded as worker_rejected."""
    kwargs.setdefault('max_active', MAX_ACTIVE)
    return base.serve(worker, host=host, port=port, **kwargs)

data.gateway.py:
"""Shared application gateway for cross-zone DAG traffic (owned server Pod), hardened version of the
real-topology-live/wan_gateway.py relay pattern (that file is unchanged).

Differences from wan_gateway.py: finite socket inactivity timeout AND absolute read deadline for request line + headers +
body; the whole upstream transfer (connect .. last response byte, bounded_http.exchange) ends at min(UPSTREAM_CAP_S, the
request's own budget_s read from the binary-framing metadata) and upstream bodies above MAX_BODY are refused (502); a peer
allow-list that is frozen once (POST /peers, later changes refused); per-target counters with an explicit drain/reset
call that refuses while relayed requests are still active, so accounting cannot leak across policy runs.
Bandwidth/delay are NOT implemented here: an optional owned-netns tc qdisc (net_control.py in the netctl sidecar)
shapes this Pod's egress. That is a gateway constraint, not physical link manipulation; the unshaped relay is the
mandatory control for the relay's own overhead.
  POST /to/<peer>/<path>  relay (allow-listed peer only)      GET /health  counters, active, peers sha, frozen
  POST /peers {peers{key:{url,zone}}}  freeze once           POST /reset {label}  returns and clears counters (active==0 only)
"""
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import hashlib
import json
import os
import socket
import struct
import threading
import time

from bounded_http import exchange

UPSTREAM_CAP_S = float(os.environ.get('GATEWAY_UPSTREAM_CAP_S', '60'))
BODY_TIMEOUT_S = float(os.environ.get('GATEWAY_BODY_TIMEOUT_S', '30'))
READ_DEADLINE_S = float(os.environ.get('GATEWAY_READ_DEADLINE_S', '90'))
MAX_BODY = 16 * 1024 * 1024
SLOTS = int(os.environ.get('GATEWAY_SLOTS', '96'))


def budget_of(raw, content_type):
    """budget_s from the binary-framing JSON metadata (http_runtime.encode_body) or a JSON body; None if absent/invalid."""
    try:
        if content_type == 'application/x-edge-binary':
            length = struct.unpack('!I', raw[:4])[0]
            meta = json.loads(raw[4:4 + length])
        else:
            meta = json.loads(raw)
        value = float(meta.get('budget_s')) if isinstance(meta, dict) and meta.get('budget_s') is not None else None
        return value if value and value > 0 else None
    except (ValueError, struct.error, TypeError):
        return None


class Relay:
    def __init__(self, clock=time.monotonic, allowed_prefixes=('http://10.',)):
        self.allowed_prefixes = tuple(allowed_prefixes)
        self.lock, self.slots = threading.Lock(), threading.BoundedSemaphore(SLOTS)
        self.peers, self.peers_sha, self.counters, self.active, self.resets = None, None, {}, 0, []
        self.clock = clock

    def freeze(self, peers):
        with self.lock:
            if self.peers is not None:
                return 409, dict(error='peers already frozen', peers_sha256=self.peers_sha)
            for key, value in peers.items():
                if not str(value.get('url', '')).startswith(self.allowed_prefixes):
                    raise ValueError(f'peer {key}: only cluster Pod IP URLs are allowed')
            self.peers = {k: dict(url=v['url'], zone=v.get('zone')) for k, v in peers.items()}
            self.peers_sha = hashlib.sha256(json.dumps(self.peers, sort_keys=True).encode()).hexdigest()
            return 200, dict(status='frozen', peers_sha256=self.peers_sha, peers=sorted(self.peers))

    def health(self):
        with self.lock:
            return dict(status='ready', frozen=self.peers is not None, peers_sha256=self.peers_sha, active=self.active,
                        counters=json.loads(json.dumps(self.counters)), resets=len(self.resets), upstream_cap_s=UPSTREAM_CAP_S,
                        body_timeout_s=BODY_TIMEOUT_S, read_deadline_s=READ_DEADLINE_S, slots=SLOTS)

    def reset(self, label):
        with self.lock:
            if self.active:
                return 409, dict(error='relayed requests still active; drain first', active=self.active)
            snapshot = dict(label=label, at=self.clock(), counters=self.counters)
            self.counters = {}
            self.resets.append(dict(label=label, at=snapshot['at']))
            return 200, snapshot

    def count(self, target, **inc):
        with self.lock:
            item = self.counters.setdefault(target, dict(requests=0, request_body_bytes=0, response_body_bytes=0, errors=0, timeouts=0,
                                                          upstream_ms_total=0.0))
            for k, v in inc.items():
                item[k] += v

    def relay(self, target, path, raw, content_type):
        """-> (status, body bytes, content type). Never forwards to a peer outside the frozen allow-list."""
        if self.peers is None:
            return 503, json.dumps(dict(error='peers not frozen')).encode(), 'application/json'
        if target not in self.peers:
            return 403, json.dumps(dict(error='peer not allow-listed')).encode(), 'application/json'
        if not self.slots.acquire(blocking=False):
            return 429, json.dumps(dict(error='gateway relay slots exhausted', slots=SLOTS)).encode(), 'application/json'
        with self.lock:
            self.active += 1
        started = self.clock()
        timeout = min(UPSTREAM_CAP_S, budget_of(raw, content_type) or UPSTREAM_CAP_S)
        try:
            status, body, _ = exchange(self.peers[target]['url'] + '/' + path, raw, content_type, timeout, MAX_BODY)
            self.count(target, requests=1, request_body_bytes=len(raw), response_body_bytes=len(body),
                       upstream_ms_total=(self.clock()-started)*1000, errors=0 if status < 400 else 1)
            return status, body, 'application/json'
        except Exception as error:
            timed_out = isinstance(error, TimeoutError) or 'timed out' in repr(error).lower()
            self.count(target, requests=1, request_body_bytes=len(raw), errors=1, timeouts=1 if timed_out else 0,
                       upstream_ms_total=(self.clock()-started)*1000)
            return 504 if timed_out else 502, json.dumps(dict(error=repr(error)[:300], gateway_timeout_s=timeout)).encode(), 'application/json'
        finally:
            with self.lock:
                self.active -= 1
            self.slots.release()


def serve(relay, host='0.0.0.0', port=8080):
    class Handler(BaseHTTPRequestHandler):
        timeout = BODY_TIMEOUT_S

        def setup(self):
            super().setup()
            self.read_done = threading.Event()
            self.timer = threading.Timer(READ_DEADLINE_S, self._expire)
            self.timer.daemon = True
            self.timer.start()

        def _expire(self):
            if not self.read_done.is_set():
                try:
                    self.connection.shutdown(socket.SHUT_RDWR)
                except OSError:
                    pass

        def finish(self):
            self.timer.cancel()
            try:
                super().finish()
            except OSError:
                pass

        def _send(self, status, raw, content_type='application/json'):
            if isinstance(raw, dict):
                raw = json.dumps(raw).encode()
            self.send_response(status)
            self.send_header('Content-Type', content_type)
            self.send_header('Content-Length', str(len(raw)))
            self.send_header('Connection', 'close')
            self.end_headers()
            try:
                self.wfile.write(raw)
            except (BrokenPipeError, ConnectionResetError):
                pass

        def do_GET(self):
            self.read_done.set()
            self._send(200, relay.health()) if self.path == '/health' else self._send(404, dict(error='unknown path'))

        def do_POST(self):
            try:
                size = int(self.headers.get('Content-Length', 0))
                if not 0 < size <= MAX_BODY:
                    self.read_done.set()
                    self._send(413, dict(error='invalid relay body size', limit=MAX_BODY))
                    return
                raw = self.rfile.read(size)
                self.read_done.set()
                if len(raw) != size:
                    return
            except OSError:
                return
            parts = self.path.split('/', 3)
            if self.path == '/peers':
                try:
                    status, value = relay.freeze(json.loads(raw)['peers'])
                except (ValueError, KeyError) as error:
                    status, value = 400, dict(error=repr(error)[:300])
                self._send(status, value)
            elif self.path == '/reset':
                self._send(*relay.reset(json.loads(raw).get('label')))
            elif len(parts) == 4 and parts[1] == 'to':
                status, body, content_type = relay.relay(parts[2], parts[3], raw, self.headers.get('Content-Type', 'application/json'))
                self._send(status, body, content_type)
            else:
                self._send(404, dict(error='only /to/<peer>/<path>, /peers, /reset'))

        def log_message(self, *args):
            pass

    class Server(ThreadingHTTPServer):
        daemon_threads = True
    return Server((host, port), Handler)


if __name__ == '__main__':
    serve(Relay(), port=int(os.environ.get('GATEWAY_PORT', '8080'))).serve_forever()

data.bounded_http.py:
"""Absolute-deadline HTTP POST for the baseline-first DAG runtime (stdlib only; shipped next to http_runtime.py).

urllib's timeout is a per-socket-operation inactivity timeout: a peer that trickles bytes can hold a request far past
its budget, and json.load(response) reads an unbounded body. exchange() bounds the WHOLE transfer (connect, send,
status, headers, body) by one monotonic deadline -- a timer shuts the socket when it passes -- and refuses response
bodies above max_body. post() keeps the http_runtime.request contract (binary framing, JSON reply, HTTPError on >= 400)
so callers' error handling is unchanged; timeout is then the absolute budget, not an inactivity limit. control() is the
same bound for the collector's control plane (GET when body is None, else post), the qualify.http contract.
"""
import http.client
import io
import json
import socket
import threading
import time
import urllib.error
import urllib.parse

from http_runtime import encode_body

MAX_RESPONSE_BODY = 32 * 1024 * 1024


class DeadlineExceeded(TimeoutError):
    def __init__(self, timeout_s):
        super().__init__(f'timed out: absolute transfer deadline {timeout_s:.3f}s exceeded')


def exchange(url, raw, content_type, timeout_s, max_body=MAX_RESPONSE_BODY):
    """-> (status, body bytes, content type); raw None sends a GET. Raises DeadlineExceeded past timeout_s, ValueError
    above max_body."""
    if timeout_s <= 0:
        raise DeadlineExceeded(timeout_s)
    parts = urllib.parse.urlsplit(url)
    conn = http.client.HTTPConnection(parts.hostname, parts.port or 80, timeout=timeout_s)
    expired, held = threading.Event(), []  # held: the connected socket (conn.sock is dropped once the reply is read)

    def expire():
        expired.set()
        for sock in held + ([conn.sock] if conn.sock is not None else []):
            try:
                sock.shutdown(socket.SHUT_RDWR)
            except OSError:
                pass
    deadline = time.monotonic() + timeout_s
    timer = threading.Timer(timeout_s, expire)
    timer.daemon = True
    timer.start()
    response = None
    try:
        target = (parts.path or '/') + (('?' + parts.query) if parts.query else '')
        if raw is None:
            conn.request('GET', target, headers={'Connection': 'close'})
        else:
            conn.request('POST', target, raw, {'Content-Type': content_type, 'Content-Length': str(len(raw)), 'Connection': 'close'})
        held.append(conn.sock)
        if expired.is_set():
            expire()
        response = conn.getresponse()
        declared = response.getheader('Content-Length')
        if declared is not None and int(declared) > max_body:
            raise ValueError(f'response body {declared} B exceeds {max_body} B')
        chunks, size = [], 0
        while True:
            chunk = response.read(min(65536, max_body + 1 - size))
            if not chunk:
                break
            chunks.append(chunk)
            size += len(chunk)
            if size > max_body:
                raise ValueError(f'response body exceeds {max_body} B')
        if expired.is_set() or time.monotonic() > deadline:
            raise DeadlineExceeded(timeout_s)
        return response.status, b''.join(chunks), response.getheader('Content-Type', 'application/json')
    except (OSError, http.client.HTTPException) as error:
        if expired.is_set() or time.monotonic() > deadline:
            raise DeadlineExceeded(timeout_s) from error
        raise
    finally:
        timer.cancel()
        if response is not None:
            response.close()
        conn.close()


def post(url, data, timeout=60, max_body=MAX_RESPONSE_BODY):
    """http_runtime.request with an absolute transfer deadline and a response-body cap."""
    raw, content_type = encode_body(data)
    status, body, _ = exchange(url, raw, content_type, timeout, max_body)
    if status >= 400:
        raise urllib.error.HTTPError(url, status, 'upstream error', {}, io.BytesIO(body))
    return json.loads(body)


def control(url, body=None, timeout=60, max_body=MAX_RESPONSE_BODY):
    """qualify.http (GET when body is None, else POST; JSON reply; HTTPError on >= 400) with the absolute deadline and cap."""
    if body is not None:
        return post(url, body, timeout, max_body)
    status, raw, _ = exchange(url, None, None, timeout, max_body)
    if status >= 400:
        raise urllib.error.HTTPError(url, status, 'control error', {}, io.BytesIO(raw))
    return json.loads(raw)

data.policies.py:
"""Existing-method placement policies over one shared 5-task DAG, one cost model and one observation stream.

Stdlib only: imported by the edge generator Pod (decisions are made at the request origin) and by local tests.

DAG (edge origin):  origin -image-> image_preprocess -tensor-> vision -feature-> fusion_join
                    origin -audio-> audio_preprocess -input_values-> speech -text-> fusion_join ; answer -> origin
A plan maps every task to one worker key. A worker key is one process on one allocated device unit; tasks placed on
the same worker share its one-unit lock (they queue), so the cost model serializes them.

Cost model (prediction only, never used as a result): list scheduling of the 5 tasks with
  compute_ms[(task, worker)]  measured closed-loop service time (profile phase receipts; synthetic only in tests)
  link (latency_ms, ms_per_byte) per ordered (src, dst) location, measured by route probes under the current network
  payload_bytes per edge kind, measured
  queue_ms(worker) = observed queue length x observed mean service time  (only policies with uses_observation)
Policies (names are generic and honest; none is a named-paper reproduction):
  fixed                  one frozen heterogeneous plan (control)
  task_fastest           per task the fastest quality-eligible worker by compute only (no transfer, no queue)
  greedy_comm            topological greedy: per task the worker with the earliest predicted finish incl. transfer + queue
  dag_static             exact enumeration of all eligible plans on the frozen profile once (empty queues), then fixed.
                         Exact enumeration is a diagnostic selector for the PREDICTED cost model, not an online goodput
                         oracle or upper bound.
  dag_reopt              the same enumeration per request with the current observation
  dag_reopt_hysteresis   dag_reopt that switches only if the predicted gain > max(rel x current, abs_ms) after a dwell time
Prior systems (JellyBean, OctopInf, ...) have adapter slots that raise NotImplementedError until their contracts are
audited and implemented; no generic policy is labelled with their names.

unstable-network copy (source experiments/quality-network-baselines/policies.py, sha256 recorded in the plan's
copied_sources). Changes, nothing else:
  - Observation keeps, per worker, the last SUCCESSFUL queue state and its time; a failed poll records only its error,
    error time and error streak (it never becomes an empty queue and never refreshes the success time). A worker that
    never answered has no queue estimate (PolicyError, never 0).
  - Every observation-driven policy uses one rule: if any candidate worker never answered or its last success is older
    than stale_after_s, the decision is that policy's own static plan (its choice on the frozen profile with no queue,
    e.g. dag_reopt -> the dag_static plan) and the decision records fallback{reason, never, stale}. This is a defect fix
    of the observation input, not a new algorithm.
  - dag_reopt_no_network: dag_reopt with the same observation, queue, compute estimates and feasible plans, but every
    transfer costs 0 in the SELECTION only; the recorded predicted_ms keeps the full (network) cost model and the data
    path is unchanged.
"""
import itertools
import time

TASKS = ('image_preprocess', 'vision', 'audio_preprocess', 'speech', 'fusion')
PREPROCESS = ('image_preprocess', 'audio_preprocess')
ORIGIN = 'origin'
# (src task or origin, dst task or origin, payload kind)
EDGES = ((ORIGIN, 'image_preprocess', 'image'), ('image_preprocess', 'vision', 'image_tensor'), ('vision', 'fusion', 'feature'),
         (ORIGIN, 'audio_preprocess', 'audio'), ('audio_preprocess', 'speech', 'input_values'), ('speech', 'fusion', 'text'),
         ('fusion', ORIGIN, 'answer'))
PREDS = {t: [(s, k) for s, d, k in EDGES if d == t] for t in TASKS}


class PolicyError(RuntimeError):
    pass


def plan_key(plan):
    return tuple(plan[t] for t in TASKS)


def plan_label(plan):
    return '|'.join(f'{t}={plan[t]}' for t in TASKS)


class Profile:
    """Measured (or, in tests only, synthetic) inputs to the cost model. `source` must say which."""

    def __init__(self, compute_ms, links, payload_bytes, source, default_link=None):
        self.compute_ms = {tuple(k) if not isinstance(k, tuple) else k: float(v) for k, v in dict(compute_ms).items()}
        self.links = {tuple(k) if not isinstance(k, tuple) else k: dict(v) for k, v in dict(links).items()}
        self.payload_bytes = dict(payload_bytes)
        self.source = source
        self.default_link = default_link

    @classmethod
    def from_json(cls, value):
        split = lambda k: tuple(k.split('->')) if '->' in k else tuple(k.split('@'))
        return cls({split(k): v for k, v in value['compute_ms'].items()}, {split(k): v for k, v in value['links'].items()},
                   value['payload_bytes'], value['source'], value.get('default_link'))

    def to_json(self):
        return dict(compute_ms={f'{t}@{w}': v for (t, w), v in self.compute_ms.items()},
                    links={f'{a}->{b}': v for (a, b), v in self.links.items()}, payload_bytes=self.payload_bytes, source=self.source,
                    default_link=self.default_link)

    def compute(self, task, worker):
        try:
            return self.compute_ms[(task, worker)]
        except KeyError:
            raise PolicyError(f'no measured compute for {task}@{worker}') from None

    def transfer(self, src, dst, kind):
        link = self.links.get((src, dst)) or self.default_link
        if link is None:
            raise PolicyError(f'no measured link {src}->{dst}')
        return float(link['latency_ms']) + float(link['ms_per_byte']) * float(self.payload_bytes[kind])


class Observation:
    """What every policy may see at decision time: per-worker last successful queue state with its time and the last poll
    error (same poller for all policies), and estimates updated from completed requests' receipts (EWMA). Static policies
    ignore it; the state is still recorded with every decision."""

    def __init__(self, alpha=0.3):
        self.alpha, self.workers, self.service_ms, self.compute_est, self.link_est = alpha, {}, {}, {}, {}

    def record_poll(self, worker, state, error, at):
        """One poll result. error None = success (state = {waiting, active, joins_open}); otherwise only the error is kept."""
        w = dict(self.workers.get(worker) or dict(state=None, success_at=None, last_error=None, error_at=None, consecutive_errors=0,
                                                  polls=0, errors=0))
        w['polls'] += 1
        if error is None:
            w.update(state=dict(state), success_at=at, consecutive_errors=0)
        else:
            w.update(last_error=str(error)[:120], error_at=at, consecutive_errors=w['consecutive_errors'] + 1, errors=w['errors'] + 1)
        self.workers = dict(self.workers, **{worker: w})  # replaced whole: a reader never sees a half-updated worker

    def carry_polls(self, other):
        self.workers = dict(other.workers)

    def freshness(self, now, workers, stale_after_s):
        never = sorted(k for k in workers if (self.workers.get(k) or {}).get('success_at') is None)
        ages = {k: (now - self.workers[k]['success_at']) * 1000 for k in workers if k not in never}
        stale = sorted(k for k, age in ages.items() if age > stale_after_s * 1000)
        return dict(never=never, stale=stale, max_age_ms=max(ages.values()) if ages else None, stale_after_s=stale_after_s)

    def _ewma(self, table, key, value):
        old = table.get(key)
        table[key] = value if old is None else (1 - self.alpha) * old + self.alpha * value

    def record_receipt(self, task, worker, wall_ms):
        self._ewma(self.compute_est, (task, worker), wall_ms)
        self._ewma(self.service_ms, worker, wall_ms)

    def record_transfer(self, src, dst, transfer_ms, payload_bytes, latency_ms):
        if payload_bytes > 0 and transfer_ms > latency_ms:
            self._ewma(self.link_est, (src, dst), (transfer_ms - latency_ms) / payload_bytes)

    def queue_ms(self, worker, profile):
        q = (self.workers.get(worker) or {}).get('state')
        if q is None:
            raise PolicyError(f'no successful queue observation of {worker}')
        depth = int(q.get('waiting', 0)) + int(q.get('active', 0))
        if not depth:
            return 0.0
        service = self.service_ms.get(worker)
        if service is None:
            known = [v for (t, w), v in profile.compute_ms.items() if w == worker]
            service = sum(known) / len(known) if known else 0.0
        return depth * service

    def to_json(self, now=None, stale_after_s=None):
        """Per-worker times (age of the last success, last error and its age, error streak) and, separately, the summary."""
        workers = {}
        for key, w in self.workers.items():
            q = w['state'] or {}
            workers[key] = dict(waiting=q.get('waiting'), active=q.get('active'), joins_open=q.get('joins_open'),
                                age_ms=(now - w['success_at']) * 1000 if now is not None and w['success_at'] is not None else None,
                                last_error=w['last_error'],
                                error_age_ms=(now - w['error_at']) * 1000 if now is not None and w['error_at'] is not None else None,
                                consecutive_errors=w['consecutive_errors'], polls=w['polls'], errors=w['errors'])
        out = dict(workers=workers, compute_est={f'{t}@{w}': v for (t, w), v in self.compute_est.items()},
                   link_ms_per_byte={f'{a}->{b}': v for (a, b), v in self.link_est.items()})
        if now is not None and stale_after_s is not None:
            out['summary'] = self.freshness(now, sorted(self.workers), stale_after_s)
        return out


class LiveProfile(Profile):
    """Profile view with observation estimates overlaid (used by observation-driven policies only)."""

    def __init__(self, base, observation):
        self.base, self.obs = base, observation
        self.payload_bytes, self.source, self.default_link = base.payload_bytes, base.source + '+observed', base.default_link
        self.compute_ms = {**base.compute_ms, **observation.compute_est}
        self.links = {}
        for key, link in base.links.items():
            per_byte = observation.link_est.get(key)
            self.links[key] = dict(link, ms_per_byte=per_byte) if per_byte is not None else link


def location(task, plan):
    return ORIGIN if task == ORIGIN else plan[task]


def predict(plan, profile, observation=None):
    """Predicted end-to-end ms of one request under the plan: list scheduling, tasks on one worker serialized, current
    queue (if observation is given) delays a worker's first free time. Returns dict(makespan_ms, tasks{t: start,end})."""
    free = {}
    if observation is not None:
        for w in set(plan.values()):
            free[w] = observation.queue_ms(w, profile)
    done, times = {}, {}
    pending = list(TASKS)
    while pending:
        ready = []
        for t in pending:
            if all(s == ORIGIN or s in done for s, _ in PREDS[t]):
                at = max((0.0 if s == ORIGIN else done[s]) + profile.transfer(location(s, plan), plan[t], kind) for s, kind in PREDS[t])
                ready.append((at, TASKS.index(t), t))
        at, _, t = min(ready)
        w = plan[t]
        start = max(at, free.get(w, 0.0))
        end = start + profile.compute(t, w)
        free[w], done[t], times[t] = end, end, (start, end)
        pending.remove(t)
    makespan = done['fusion'] + profile.transfer(plan['fusion'], ORIGIN, 'answer')
    return dict(makespan_ms=makespan, tasks=times)


class QualityGate:
    """Quality eligibility of whole pipeline plans, independent of numerical parity.

    mode 'strict': a plan is eligible only if its pipeline quality evidence (measured on the plan, or inferred because
    every task output equals the reference-composition output on all evaluated inputs) meets qmin. Parity failure alone
    never excludes a plan; parity success alone never qualifies one.
    mode 'diagnostic': every executable plan is selectable but every result is labelled diagnostic (not a same-quality
    comparison). Used while no plan meets qmin (2026-10-23: 0.355 < 0.40 on the reused 60 pairs)."""

    def __init__(self, mode, qmin, evidence=None):
        if mode not in ('strict', 'diagnostic'):
            raise ValueError('quality mode must be strict or diagnostic')
        self.mode, self.qmin, self.evidence = mode, float(qmin), {tuple(k.split('|')) if isinstance(k, str) else tuple(k): v
                                                               for k, v in (evidence or {}).items()}

    def eligible(self, plan):
        if self.mode == 'diagnostic':
            return True
        item = self.evidence.get(plan_key(plan))
        return bool(item) and item.get('source') in ('measured', 'identical_outputs') and item.get('quality') is not None \
            and float(item['quality']) >= self.qmin

    def label(self):
        return 'diagnostic (quality gate not met; not a same-quality comparison)' if self.mode == 'diagnostic' else f'strict qmin={self.qmin}'


def all_plans(candidates, gate):
    for combo in itertools.product(*(candidates[t] for t in TASKS)):
        plan = dict(zip(TASKS, combo))
        if gate.eligible(plan):
            yield plan


class Decision(dict):
    pass


class Policy:
    name, uses_observation = None, False

    def __init__(self, candidates, gate, profile, stale_after_s=3.0):
        self.candidates, self.gate, self.profile = {t: list(candidates[t]) for t in TASKS}, gate, profile
        self.plans = list(all_plans(self.candidates, gate))
        if not self.plans:
            raise PolicyError(f'no quality-eligible plan ({gate.label()})')
        self._prefix = {}
        self.stale_after_s, self.workers = float(stale_after_s), sorted({w for ws in self.candidates.values() for w in ws})
        self._static = None

    def static_plan(self):
        """This policy's own choice on the frozen profile with no queue (the verified fallback for unusable observation)."""
        if self._static is None:
            self._static = dict(self.choose(None, 0.0)[0])
        return self._static

    def fallback(self, observation, now):
        if not self.uses_observation:
            return None
        fresh = observation.freshness(now, self.workers, self.stale_after_s) if observation is not None else \
            dict(never=list(self.workers), stale=[], max_age_ms=None, stale_after_s=self.stale_after_s)
        if not fresh['never'] and not fresh['stale']:
            return None
        return dict(fresh, reason='no_successful_poll' if fresh['never'] else 'stale_observation',
                    rule='static plan on the frozen profile (no queue); never an empty-queue reading of a failed poll')

    def view(self, observation):
        return LiveProfile(self.profile, observation) if self.uses_observation and observation is not None else self.profile

    def feasible_prefix(self, partial):
        key = tuple(sorted(partial.items()))
        if key not in self._prefix:
            self._prefix[key] = any(all(p[t] == w for t, w in partial.items()) for p in self.plans)
        return self._prefix[key]

    def decide(self, observation=None, now=None):
        started = time.perf_counter()
        now = time.monotonic() if now is None else now
        fallback = self.fallback(observation, now)
        if fallback:
            plan, extra, profile, seen = self.static_plan(), {}, self.profile, None
        else:
            plan, extra = self.choose(observation, now)
            profile, seen = self.view(observation), observation if self.uses_observation else None
        predicted = predict(plan, profile, seen)
        return Decision(policy=self.name, plan=dict(plan), plan_label=plan_label(plan), predicted_ms=predicted['makespan_ms'],
                        decision_ms=(time.perf_counter()-started)*1000, uses_observation=self.uses_observation, fallback=fallback,
                        **extra)

    def choose(self, observation, now):
        raise NotImplementedError


class Fixed(Policy):
    name = 'fixed'

    def __init__(self, candidates, gate, profile, plan):
        super().__init__(candidates, gate, profile)
        if any(plan[t] not in self.candidates[t] for t in TASKS) or not gate.eligible(plan):
            raise PolicyError(f'fixed plan {plan_label(plan)} is not an eligible candidate plan')
        self.plan = dict(plan)

    def choose(self, observation, now):
        return self.plan, {}


class TaskFastest(Policy):
    """Per task (fixed task order) the eligible worker with the smallest measured compute; transfer and queue ignored.
    Ties break by candidate order. Decided once from the frozen profile (it uses no observation)."""
    name = 'task_fastest'

    def __init__(self, candidates, gate, profile, stale_after_s=3.0):
        super().__init__(candidates, gate, profile, stale_after_s)
        partial = {}
        for t in TASKS:
            options = [w for w in self.candidates[t] if self.feasible_prefix(dict(partial, **{t: w}))]
            partial[t] = min(options, key=lambda w: (profile.compute(t, w), self.candidates[t].index(w)))
        self.plan = partial

    def choose(self, observation, now):
        return self.plan, {}


class GreedyComm(Policy):
    """Topological greedy per request: tasks in ready order; each takes the eligible worker with the earliest predicted
    finish given the choices already made, transfer from its predecessors' locations, the worker's current queue and
    tasks already assigned to it in this request. No look-ahead (the fan-in cost of later tasks is not considered)."""
    name, uses_observation = 'greedy_comm', True

    def choose(self, observation, now):
        profile = self.view(observation)
        free = {}
        if observation is not None:
            for w in {w for ws in self.candidates.values() for w in ws}:
                free[w] = observation.queue_ms(w, profile)
        partial, done = {}, {}
        for t in ('image_preprocess', 'audio_preprocess', 'vision', 'speech', 'fusion'):
            best = None
            for w in self.candidates[t]:
                if not self.feasible_prefix(dict(partial, **{t: w})):
                    continue
                at = max((0.0 if s == ORIGIN else done[s]) + profile.transfer(ORIGIN if s == ORIGIN else partial[s], w, kind)
                         for s, kind in PREDS[t])
                end = max(at, free.get(w, 0.0)) + profile.compute(t, w)
                score = end + (profile.transfer(w, ORIGIN, 'answer') if t == 'fusion' else 0.0)
                if best is None or score < best[0]:
                    best = (score, end, w)
            _, end, w = best
            partial[t], done[t], free[w] = w, end, end
        return partial, {}


class DagStatic(Policy):
    """Exact enumeration of all eligible plans on the frozen profile (no queue), chosen once. Diagnostic selector."""
    name = 'dag_static'

    def __init__(self, candidates, gate, profile, stale_after_s=3.0):
        super().__init__(candidates, gate, profile, stale_after_s)
        self.plan, self.ranked = best_plan(self.plans, profile, None)

    def choose(self, observation, now):
        return self.plan, dict(enumerated=len(self.plans))


def best_plan(plans, profile, observation):
    scored = sorted(((predict(p, profile, observation)['makespan_ms'], plan_key(p), p) for p in plans), key=lambda x: (x[0], x[1]))
    return dict(scored[0][2]), [(s, k) for s, k, _ in scored[:5]]


class DagReopt(Policy):
    """Same enumeration per request with the current observation (queues + receipt EWMA)."""
    name, uses_observation = 'dag_reopt', True

    def choose(self, observation, now):
        plan, ranked = best_plan(self.plans, self.view(observation), observation)
        return plan, dict(enumerated=len(self.plans))


class DagReoptHysteresis(DagReopt):
    name = 'dag_reopt_hysteresis'

    def __init__(self, candidates, gate, profile, rel=0.15, abs_ms=50.0, dwell_s=5.0, stale_after_s=3.0):
        super().__init__(candidates, gate, profile, stale_after_s)
        self.rel, self.abs_ms, self.dwell_s = float(rel), float(abs_ms), float(dwell_s)
        self.current, self.switched_at, self.switches = None, None, 0

    def static_plan(self):
        """dag_reopt's static plan; computing it must not start the hysteresis state (a fallback leaves current/dwell as is)."""
        if self._static is None:
            self._static = dict(DagReopt.choose(self, None, 0.0)[0])
        return self._static

    def choose(self, observation, now):
        profile = self.view(observation)
        best, _ = best_plan(self.plans, profile, observation)
        if self.current is None:
            self.current, self.switched_at = best, now
            return best, dict(enumerated=len(self.plans), switched=True, hold_reason='initial')
        current_ms = predict(self.current, profile, observation)['makespan_ms']
        best_ms = predict(best, profile, observation)['makespan_ms']
        gain = current_ms - best_ms
        dwell_ok = now - self.switched_at >= self.dwell_s
        if plan_key(best) != plan_key(self.current) and gain > max(self.rel * current_ms, self.abs_ms) and dwell_ok:
            self.current, self.switched_at = best, now
            self.switches += 1
            return best, dict(enumerated=len(self.plans), switched=True, predicted_gain_ms=gain)
        reason = 'same plan' if plan_key(best) == plan_key(self.current) else ('dwell' if not dwell_ok else 'gain below threshold')
        return self.current, dict(enumerated=len(self.plans), switched=False, hold_reason=reason, predicted_gain_ms=gain)


class ZeroTransfer(Profile):
    """Selection view of the network-cost ablation: the same compute estimates and payloads, every transfer costs 0."""

    def __init__(self, base):
        self.base, self.compute_ms, self.links, self.payload_bytes = base, base.compute_ms, base.links, base.payload_bytes
        self.source, self.default_link = base.source + '+no-network-cost', base.default_link

    def transfer(self, src, dst, kind):
        return 0.0


class DagReoptNoNetwork(DagReopt):
    """dag_reopt with transfer cost 0 in the selection only (same observation, queue, compute, feasibility, data path).
    decide() records predicted_ms from the full cost model; selection_cost_ms is the no-network makespan."""
    name = 'dag_reopt_no_network'

    def choose(self, observation, now):
        view = ZeroTransfer(self.view(observation))
        plan, ranked = best_plan(self.plans, view, observation)
        return plan, dict(enumerated=len(self.plans), uses_network_cost=False, selection_cost_ms=ranked[0][0])


class PriorSystemAdapter(Policy):
    """Slot for a near prior system ported onto this executor. Not implemented until its contract (paper version,
    official code revision, objective, inputs, decision unit, backend adaptation) is audited; never substituted."""
    paper, audit = None, None

    def __init__(self, *args, **kwargs):
        raise NotImplementedError(f'{self.name}: prior-system adapter not implemented ({self.audit})')


class JellyBeanAdapter(PriorSystemAdapter):
    name, paper, audit = 'jellybean', 'JellyBean (MLSys 2022)', 'contract audit owned by the coordinator/root; not implemented here'


class OctopInfAdapter(PriorSystemAdapter):
    name, paper, audit = 'octopinf', 'OctopInf', 'contract audit owned by the coordinator/root; not implemented here'


POLICIES = {c.name: c for c in (Fixed, TaskFastest, GreedyComm, DagStatic, DagReopt, DagReoptHysteresis, DagReoptNoNetwork)}
PRIOR_ADAPTERS = {c.name: c for c in (JellyBeanAdapter, OctopInfAdapter)}


def build(spec, candidates, gate, profile, stale_after_s=3.0):
    """spec: {name, plan? (fixed), rel/abs_ms/dwell_s (hysteresis)}; stale_after_s is the observation contract."""
    name = spec['name']
    if name in PRIOR_ADAPTERS:
        return PRIOR_ADAPTERS[name](candidates, gate, profile)
    cls = POLICIES[name]
    if cls is Fixed:
        return cls(candidates, gate, profile, spec['plan'])
    if cls is DagReoptHysteresis:
        return cls(candidates, gate, profile, **{k: spec[k] for k in ('rel', 'abs_ms', 'dwell_s') if k in spec}, stale_after_s=stale_after_s)
    return cls(candidates, gate, profile, stale_after_s=stale_after_s)


def link_fit(small, large):
    """Two-point fit from probe medians: (bytes_small, ms_small), (bytes_large, ms_large) -> latency_ms, ms_per_byte >= 0."""
    (b0, t0), (b1, t1) = small, large
    per_byte = max(0.0, (t1 - t0) / (b1 - b0)) if b1 != b0 else 0.0
    return dict(latency_ms=max(0.0, t0 - per_byte * b0), ms_per_byte=per_byte, effective_mbps=(8 / (per_byte * 1000)) if per_byte else None)

data.netctl.py:
"""netctl sidecar of the owned gateway Pod: the ONLY holder of a network trace. It applies the pre-registered trace
(traces.py) to this Pod's own netns egress on the edge<->server path and records every application.

qdisc tree (same shape as real-topology-live/net_control.py, which is unchanged): root prio 1: (bands 3, priomap -> 1:3
unshaped default), band 1:1 = gateway -> cloud Pod IPs, band 1:2 = gateway -> edge Pod IPs (u32 /32 dst filters); each
shaped band is tbf (rate, burst 4096 B, limit 131072 B) -> netem (delay, jitter, loss, limit 64 packets).

Difference from net_control.py: a phase boundary never deletes and re-creates the root. The tree is installed once per
cell (phase 0); every later phase is an in-place `tc qdisc change` of each band's tbf and netem (RTM_NEWQDISC with
NLM_F_REPLACE via pyroute2 'change'), so queued packets, handles, filters and counters survive the boundary (verified on
the real kernel by test_netctl.RealKernelChange). Teardown (root delete) happens only between cells after the collector's
drain/idle barrier, and on exit. pyroute2 0.9.6 has no TCA_NETEM_PRNG_SEED, so netem loss/jitter draws are not seeded:
the trace is reproducible at the configuration level only, never packet by packet.

HTTP (port 8081, this Pod netns): GET /health, GET /status?label=L,
POST /arm {run_id, label, trace, trace_sha256, cloud[ip], edge[ip]} | /start {run_id, label, delay_s} |
     /restore {run_id, label} (cancel pending phases, change to good) | /teardown {run_id} | /snapshot {run_id}
Only approved, frozen trace names are accepted (never phases from the wire). Times are this Pod's monotonic clock; the
collector aligns them with the generator's clock from its own call round trips (it never subtracts cross-host clocks).
"""
from datetime import datetime, timezone
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import ipaddress
import json
import os
from pathlib import Path
import signal
import sys
import threading
import time
import urllib.parse

sys.path.insert(0, str(Path(__file__).resolve().parent))
import traces  # noqa: E402

ROOT_HANDLE = 0x10000
BANDS = ((1, 'cloud'), (2, 'edge'))
TBF = dict(burst=4096, limit=131072)  # frozen from net_control.py
NETEM_LIMIT = 64                     # frozen from net_control.py: TCP drops/retransmissions are measured, not hidden
MAX_DELAY_S = 10.0
MAX_BODY = 64 * 1024


def pod_ip(value):
    result = str(ipaddress.IPv4Address(value))
    if not result.startswith('10.'):
        raise ValueError('Only frozen cluster Pod IPs are allowed')
    return result


def utc():
    return datetime.now(timezone.utc).isoformat(timespec='milliseconds')


class Pyroute2Tc:
    """tc in THIS process's netns only (env RESEARCH_LINK_CONTROL=owned-pod-netns, as net_control.py)."""

    def __init__(self, ifname='eth0'):
        if os.environ.get('RESEARCH_LINK_CONTROL') != 'owned-pod-netns':
            raise RuntimeError('Refusing unowned network namespace')
        from pyroute2 import IPRoute
        self.IPRoute, self.ifname = IPRoute, ifname

    def _index(self, ip):
        return ip.link_lookup(ifname=self.ifname)[0]

    @staticmethod
    def _roots(ip, index):
        return [q['handle'] for q in ip.get_qdiscs(index=index) if q['parent'] == 0xffffffff]

    @staticmethod
    def _tbf(cond):
        return dict(rate=f"{cond['mbps']}mbit", **TBF)

    @staticmethod
    def _netem(cond):
        return dict(delay=cond['delay_ms'] * 1000, jitter=cond['jitter_ms'] * 1000, loss=cond['loss_pct'], limit=NETEM_LIMIT)

    def install(self, cond, cloud, edge):
        with self.IPRoute() as ip:
            index = self._index(ip)
            roots = self._roots(ip, index)
            if ROOT_HANDLE in roots:
                raise RuntimeError('owned root qdisc already present; teardown first')
            if any(h != 0 for h in roots):
                raise RuntimeError('Unrelated root qdisc; refusing replacement')
            ip.tc('add', 'prio', index, '1:', bands=3, priomap=[2] * 16)
            targets = dict(cloud=cloud, edge=edge)
            for band, zone in BANDS:
                ip.tc('add', 'tbf', index, f'{band}0:', parent=f'1:{band}', **self._tbf(cond))
                ip.tc('add', 'netem', index, f'{band}1:', parent=f'{band}0:1', **self._netem(cond))
                for priority, value in enumerate(targets[zone], band * 100):
                    dst = pod_ip(value)
                    ip.tc('add-filter', 'u32', index, parent='1:', prio=priority, protocol=0x0800, target=f'1:{band}',
                          keys=[f'{hex(int(ipaddress.IPv4Address(dst)))}/0xffffffff+16'])

    def change(self, cond):
        with self.IPRoute() as ip:
            index = self._index(ip)
            if ROOT_HANDLE not in self._roots(ip, index):
                raise RuntimeError('owned root qdisc missing; refusing to create one during a trace')
            for band, _ in BANDS:
                ip.tc('change', 'tbf', index, f'{band}0:', parent=f'1:{band}', **self._tbf(cond))
                ip.tc('change', 'netem', index, f'{band}1:', parent=f'{band}0:1', **self._netem(cond))

    def teardown(self):
        with self.IPRoute() as ip:
            index = self._index(ip)
            if ROOT_HANDLE in self._roots(ip, index):
                ip.tc('del', 'prio', index, '1:')

    def snapshot(self):
        with self.IPRoute() as ip:
            index = self._index(ip)
            summary = []
            for q in ip.get_qdiscs(index=index):
                stats = q.get_attr('TCA_STATS')
                if stats is None:
                    raise RuntimeError('Kernel queue stats unavailable; refuse false idle')
                summary.append(dict(handle=q['handle'], parent=q['parent'], kind=q.get_attr('TCA_KIND'), bytes=int(stats['bytes']),
                                    packets=int(stats['packets']), drops=int(stats['drop']), overlimits=int(stats['overlimits']),
                                    qlen=int(stats['qlen']), backlog=int(stats['backlog'])))
            filters = len(list(ip.get_filters(index=index, parent=ROOT_HANDLE))) if ROOT_HANDLE in self._roots(ip, index) else 0
            # Parent/child stats overlap (tbf counts what its netem child holds); never sum them as traffic.
            return dict(observer='native-TCA_STATS', netns=os.readlink('/proc/self/ns/net'), qdisc_summary=summary,
                        installed=ROOT_HANDLE in self._roots(ip, index), filters=filters)


class Runner:
    """Arms one cell's trace (install phase 0), runs it from a start command (in-place change per boundary), restores and
    tears down. clock/wait are the time seam (wait(event, timeout) -> event set)."""

    def __init__(self, tc, clock=time.monotonic, wait=None, run_id=None, wall=utc):
        self.tc, self.clock, self.wall, self.run_id = tc, clock, wall, run_id
        self.wait = wait or (lambda event, timeout: event.wait(timeout))
        self.lock, self.cells, self.current, self.installed = threading.Lock(), {}, None, False

    def _check_run(self, body):
        if self.run_id is None or body.get('run_id') != self.run_id:
            raise ValueError('run_id does not match this gateway Pod')

    def _snapshot(self):
        try:
            return self.tc.snapshot()
        except Exception as error:
            return dict(error=repr(error)[:300])

    def _event(self, cell, kind, **fields):
        cell['events'].append(dict(kind=kind, local=self.clock(), wall_utc=self.wall(), **fields))

    def arm(self, body):
        self._check_run(body)
        name, label = body.get('trace'), body.get('label')
        if name not in traces.TRACES:
            raise ValueError(f'unapproved trace {name!r}')
        if body.get('trace_sha256') != traces.trace_sha256(name):
            raise ValueError('trace_sha256 does not match the frozen trace table')
        cloud, edge = [pod_ip(v) for v in body.get('cloud') or []], [pod_ip(v) for v in body.get('edge') or []]
        if not cloud or not edge:
            raise ValueError('cloud and edge targets are required')
        with self.lock:
            if self.installed:
                raise ValueError('a trace is still installed; restore and teardown first')
            if not label or label in self.cells:
                raise ValueError('label missing or reused')
            phases = traces.TRACES[name]
            cell = dict(label=label, trace=name, trace_sha256=body['trace_sha256'], state='armed', events=[], cancel=threading.Event(),
                        thread=None, cloud=cloud, edge=edge)
            self.tc.install(traces.condition(phases[0]), cloud, edge)
            self.installed, self.current = True, label
            self.cells[label] = cell
            self._event(cell, 'install', phase=0, name=phases[0]['name'], condition=traces.condition(phases[0]), stats=self._snapshot())
        return dict(status='armed', label=label, trace=name)

    def start(self, body):
        self._check_run(body)
        delay = float(body.get('delay_s', 0))
        if not 0 < delay <= MAX_DELAY_S:
            raise ValueError(f'delay_s must be in (0, {MAX_DELAY_S}]')
        with self.lock:
            cell = self.cells.get(body.get('label'))
            if cell is None or cell['state'] != 'armed' or self.current != cell['label']:
                raise ValueError('label is not the armed, unstarted trace')
            received = self.clock()
            cell.update(state='running', received_local=received, start_local=received + delay, delay_s=delay)
            cell['thread'] = threading.Thread(target=self._run, args=(cell,), daemon=True)
            cell['thread'].start()
        return dict(status='started', label=cell['label'], received_local=received, start_local=cell['start_local'])

    def _sleep_until(self, cell, deadline):
        while True:
            remaining = deadline - self.clock()
            if remaining <= 0:
                return True
            if self.wait(cell['cancel'], min(remaining, 0.05)) or cell['cancel'].is_set():
                return False

    def _run(self, cell):
        phases, t0 = traces.TRACES[cell['trace']], cell['start_local']
        for i, p in enumerate(phases[1:], 1):
            planned = t0 + p['start_s']
            if not self._sleep_until(cell, planned):
                return
            begun = self.clock()
            try:
                self.tc.change(traces.condition(p))
            except Exception as error:
                self._event(cell, 'change', phase=i, name=p['name'], planned_offset_s=p['start_s'], planned_local=planned,
                            apply_lag_ms=(begun - planned) * 1000, call_ms=(self.clock() - begun) * 1000, condition=traces.condition(p),
                            ok=False, error=repr(error)[:300])
                cell['state'] = 'failed'
                self._restore_good(cell, 'restore_after_error')
                return
            ended = self.clock()
            self._event(cell, 'change', phase=i, name=p['name'], planned_offset_s=p['start_s'], planned_local=planned,
                        applied_start_local=begun, applied_end_local=ended, apply_lag_ms=(begun - planned) * 1000,
                        call_ms=(ended - begun) * 1000, condition=traces.condition(p), ok=True, stats=self._snapshot())
        if self._sleep_until(cell, t0 + phases[-1]['end_s']):
            self._event(cell, 'window_end', planned_offset_s=phases[-1]['end_s'], stats=self._snapshot())
            cell['state'] = 'completed'

    def _restore_good(self, cell, kind):
        begun = self.clock()
        try:
            self.tc.change(traces.GOOD)
            self._event(cell, kind, condition=dict(traces.GOOD), ok=True, call_ms=(self.clock() - begun) * 1000, stats=self._snapshot())
        except Exception as error:
            self._event(cell, kind, condition=dict(traces.GOOD), ok=False, error=repr(error)[:300])

    def join(self, label, timeout=None):
        thread = self.cells[label]['thread']
        if thread is not None:
            thread.join(timeout)

    def _stop(self, cell):
        cell['cancel'].set()
        if cell['thread'] is not None:
            cell['thread'].join(5)

    def restore(self, body):
        """Cancel pending phases, then an in-place change to good (no flush); the tree stays installed for the drain."""
        self._check_run(body)
        with self.lock:
            cell = self.cells.get(body.get('label'))
            if cell is None:
                raise ValueError('unknown label')
            self._stop(cell)
            if self.installed and self.current == cell['label']:
                self._restore_good(cell, 'restore')
            if cell['state'] in ('armed', 'running'):
                cell['state'] = 'restored'
        return self.status(cell['label'])

    def teardown(self, body):
        """Root delete: only between cells (after the drain barrier) and at exit. Stats are snapshotted first."""
        self._check_run(body)
        return self.teardown_all()

    def teardown_all(self):
        with self.lock:
            cell = self.cells.get(self.current)
            if cell is not None:
                self._stop(cell)
                self._event(cell, 'pre_teardown', stats=self._snapshot())
            error = None
            try:
                self.tc.teardown()
                self.installed = False
            except Exception as exc:
                error = repr(exc)[:300]
            if cell is not None:
                self._event(cell, 'teardown', ok=error is None, error=error)
            self.current = None
        return dict(status='torn_down' if error is None else 'teardown_error', error=error, installed=self.installed)

    def status(self, label):
        cell = self.cells[label]
        return {k: v for k, v in cell.items() if k not in ('cancel', 'thread')}

    def health(self):
        return dict(ready=True, run_id=self.run_id, installed=self.installed, current=self.current, cells=sorted(self.cells),
                    traces={k: traces.trace_sha256(k) for k in traces.TRACES})


def serve(runner, host='0.0.0.0', port=8081):
    class Handler(BaseHTTPRequestHandler):
        timeout = 30

        def _send(self, status, value):
            raw = json.dumps(value, separators=(',', ':'), default=str).encode()
            self.send_response(status)
            self.send_header('Content-Type', 'application/json')
            self.send_header('Content-Length', str(len(raw)))
            self.send_header('Connection', 'close')
            self.end_headers()
            self.wfile.write(raw)

        def do_GET(self):
            url = urllib.parse.urlparse(self.path)
            try:
                if url.path == '/health':
                    self._send(200, runner.health())
                elif url.path == '/status':
                    self._send(200, runner.status(urllib.parse.parse_qs(url.query)['label'][0]))
                else:
                    self._send(404, dict(error='unknown path'))
            except (KeyError, ValueError) as error:
                self._send(400, dict(error=repr(error)[:300]))

        def do_POST(self):
            try:
                size = int(self.headers.get('Content-Length', 0))
                if not 0 < size <= MAX_BODY:
                    raise ValueError('body size')
                body = json.loads(self.rfile.read(size))
                routes = {'/arm': runner.arm, '/start': runner.start, '/restore': runner.restore, '/teardown': runner.teardown,
                          '/snapshot': lambda b: (runner._check_run(b), runner._snapshot())[1]}
                if self.path not in routes:
                    raise KeyError(self.path)
                self._send(200, routes[self.path](body))
            except (KeyError, ValueError, TypeError) as error:
                self._send(400, dict(error=repr(error)[:300]))
            except Exception as error:
                self._send(500, dict(error=repr(error)[:300]))

        def log_message(self, *args):
            pass
    return ThreadingHTTPServer((host, port), Handler)


def main():
    runner = Runner(Pyroute2Tc(os.environ.get('NETCTL_IFNAME', 'eth0')), run_id=os.environ['RUN_ID'])
    server = serve(runner, port=int(os.environ.get('NETCTL_PORT', '8081')))
    signal.signal(signal.SIGTERM, lambda *_: (_ for _ in ()).throw(SystemExit(0)))
    print(json.dumps(dict(event='netctl_ready', run_id=runner.run_id)), flush=True)
    try:
        server.serve_forever()
    finally:
        runner.teardown_all()  # never leave the owned qdisc behind on exit/error


if __name__ == '__main__':
    main()

data.traces.py:
"""Pre-registered time-varying network traces for the unstable-edge-network stress test (pure, stdlib only).

Shipped to the netctl sidecar of the owned gateway Pod (the only component that knows a trace) and used offline by the
planner and the analysis. The generator and the policies never receive a trace: they adapt from real observation only.

A trace is a list of contiguous half-open phases [start_s, end_s) that covers exactly [0, window_s). Each phase is one
egress constraint of the gateway Pod netns on the edge<->server path (tbf rate + netem delay/jitter/loss). The values
are the spec's fixed table; the traces are a controlled stress test, not a claimed distribution of real edge links.
"""
import hashlib
import json

WINDOW_S = 60
GOOD = dict(mbps=100, delay_ms=0, jitter_ms=0, loss_pct=0.0)
_MID = dict(mbps=10, delay_ms=20, jitter_ms=5, loss_pct=0.5)


def _phase(name, start, end, cond):
    return dict(name=name, start_s=start, end_s=end, **cond)


TRACES = {
    'stable': [_phase('good', 0, 60, GOOD)],
    'slow': [_phase('good', 0, 20, GOOD), _phase('slow', 20, 40, dict(mbps=10, delay_ms=20, jitter_ms=0, loss_pct=0.0)),
             _phase('good', 40, 60, GOOD)],
    'burst': [_phase('good', 0, 10, GOOD), _phase('lossy', 10, 20, _MID),
              _phase('narrow', 20, 28, dict(mbps=2, delay_ms=20, jitter_ms=5, loss_pct=1.0)),
              _phase('outage', 28, 30, dict(mbps=2, delay_ms=20, jitter_ms=5, loss_pct=100.0)),
              _phase('good', 30, 40, GOOD), _phase('lossy', 40, 50, _MID), _phase('good', 50, 60, GOOD)],
}
# Every impairment value the netctl sidecar may apply (anything else is refused before a netlink call).
APPROVED = dict(mbps=(2, 10, 100), delay_ms=(0, 20), jitter_ms=(0, 5), loss_pct=(0.0, 0.5, 1.0, 100.0))
CONDITION_KEYS = tuple(APPROVED)


def condition(phase):
    return {k: phase[k] for k in CONDITION_KEYS}


def validate(phases, window_s):
    """ValueError unless the phases are contiguous, non-empty, start at 0, end exactly at window_s and use approved values."""
    if not phases:
        raise ValueError('trace has no phase')
    previous = 0
    for i, p in enumerate(phases):
        if p['start_s'] != previous:
            raise ValueError(f'phase {i} starts at {p["start_s"]}, expected {previous} (gap, overlap or late start)')
        if not p['end_s'] > p['start_s']:
            raise ValueError(f'phase {i} is empty or reversed')
        if p['end_s'] > window_s:
            raise ValueError(f'phase {i} ends at {p["end_s"]} after the {window_s}s window')
        for key, allowed in APPROVED.items():
            if p[key] not in allowed:
                raise ValueError(f'phase {i}: {key}={p[key]!r} is not an approved value {allowed}')
        previous = p['end_s']
    if previous != window_s:
        raise ValueError(f'trace ends at {previous}, not at the {window_s}s window')
    return phases


def phase_at(phases, t):
    """Index of the phase containing offset t ([start, end) half-open), None outside [0, window)."""
    for i, p in enumerate(phases):
        if p['start_s'] <= t < p['end_s']:
            return i
    return None


def trace_sha256(name):
    return hashlib.sha256(json.dumps(TRACES[name], sort_keys=True, separators=(',', ':')).encode()).hexdigest()


for _name, _phases in TRACES.items():
    validate(_phases, WINDOW_S)

data.http_runtime.py:
"""Direct branch/join HTTP runtime. Test fixtures are explicitly labelled, not AI.

Operator adapters are bytes -> bytes; fusion adapters receive two named bytes.
Binary task bodies and JSON control. Payload counts exclude the wire envelope.
"""
import base64
from contextlib import contextmanager
import hashlib
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import json
import os
import struct
import threading
import queue
from concurrent.futures import Future
import time
import urllib.error
import urllib.request


def digest(data):
    return hashlib.sha256(data).hexdigest()


def request(url, data, timeout=60):
    raw, content_type = encode_body(data)
    opener = urllib.request.build_opener(urllib.request.ProxyHandler({}))
    req = urllib.request.Request(url, raw, {'Content-Type': content_type})
    with opener.open(req, timeout=timeout) as response:
        return json.load(response)


def encode_body(data):
    """JSON control header followed by exact binary data; no padding/base64."""
    if isinstance(data.get('data'), bytes):
        metadata = {k: v for k, v in data.items() if k != 'data'}
        header = json.dumps(metadata, separators=(',', ':')).encode()
        return struct.pack('!I', len(header)) + header + data['data'], 'application/x-edge-binary'
    return json.dumps(data, separators=(',', ':')).encode(), 'application/json'


def decode_body(raw, content_type):
    if content_type == 'application/x-edge-binary':
        if len(raw) < 4:
            raise ValueError('Truncated binary header')
        length = struct.unpack('!I', raw[:4])[0]
        if length > len(raw) - 4:
            raise ValueError('Truncated binary metadata')
        return dict(json.loads(raw[4:4 + length]), data=raw[4 + length:])
    return json.loads(raw)


def payload(data):
    return data if isinstance(data, bytes) else base64.b64decode(data, validate=True)


class ProtocolError(Exception):
    def __init__(self, message, status=400):
        super().__init__(message)
        self.status = status


def identity(data):
    values = tuple(data.get(k) for k in ('run_id', 'request_id'))
    if any(not isinstance(v, str) or not v or len(v) > 100 for v in values):
        raise ProtocolError('run_id and request_id must be nonempty short strings')
    return values


class OperatorServer(ThreadingHTTPServer):
    daemon_threads = True

    def __init__(self, address, task, adapter, metadata=None, capacity=64, ttl=120):
        super().__init__(address, Handler)
        self.task, self.adapter = task, adapter
        self.metadata = dict(metadata or {'scope': 'protocol_fixture_not_ai'})
        self.metadata.update(task=task, node=os.getenv('NODE_NAME', 'local-test'), pod_uid=os.getenv('POD_UID', 'local-test'))
        self.capacity, self.ttl = capacity, ttl
        self.entries = {}
        self.lock = threading.Lock()
        self.jobs = queue.Queue(maxsize=capacity)
        self.active = False
        self.http_active = 0
        self.worker_ready = threading.Event()
        self.worker_error = None
        self.worker = threading.Thread(target=self._work, daemon=True)
        self.worker.start()
        if not self.worker_ready.wait(60) or self.worker_error:
            raise RuntimeError('Serving worker initialization failed: ' + str(self.worker_error))
        self.tombstones = {}

    def receipt(self, inputs, output, compute_ms, queue_ms):
        return dict(self.metadata, input_bytes={k: len(v) for k, v in inputs.items()},
                    input_sha256={k: digest(v) for k, v in inputs.items()}, output_bytes=len(output),
                    output_sha256=digest(output), compute_ms=compute_ms, queue_ms=queue_ms)

    def _work(self):
        try:
            if self.metadata.get('scope') == 'real_ai_file_replay':
                import torch
                # Apply OpenMP settings in the thread that actually calls models.
                torch.set_num_threads(1)
                self.metadata['serving_torch_threads'] = torch.get_num_threads()
                self.metadata['serving_torch_interop_threads'] = torch.get_num_interop_threads()
                self.metadata['serving_native_thread_id'] = threading.get_native_id()
                self.metadata['serving_thread_initialized_utc'] = time.strftime('%Y-%m-%dT%H:%M:%SZ', time.gmtime())
                if self.metadata['serving_torch_threads'] != 1 or self.metadata['serving_torch_interop_threads'] != 1:
                    raise RuntimeError('Serving thread configuration failed')
        except Exception as error:
            self.worker_error = repr(error)
            self.worker_ready.set()
            return
        self.worker_ready.set()
        while True:
            job = self.jobs.get()
            if job is None:
                return
            inputs, arrived, deadline, future = job
            begin = time.monotonic()
            try:
                self.active = True
                if begin >= deadline:
                    raise ProtocolError('Expired in serving queue', 504)
                result = self.adapter(inputs)
                if not isinstance(result, bytes):
                    raise TypeError('Adapter must return bytes')
                end = time.monotonic()
                if end >= deadline:
                    raise ProtocolError('Expired during model execution', 504)
                future.set_result((result, (end - begin) * 1000, (begin - arrived) * 1000))
            except Exception as error:
                future.set_exception(error)
            finally:
                self.active = False
                self.jobs.task_done()

    def invoke(self, inputs, timeout=120):
        arrived, future = time.monotonic(), Future()
        try:
            self.jobs.put_nowait((inputs, arrived, arrived + timeout, future))
        except queue.Full:
            raise ProtocolError('Serving queue capacity reached', 429)
        return future.result(timeout=timeout)

    def server_close(self):
        super().server_close()
        self.jobs.put(None)

    def operate(self, path, data):
        if path == '/health':
            with self.lock:
                now = time.monotonic()
                self.entries = {k:v for k,v in self.entries.items() if now-v['created'] <= self.ttl}
                pending = sum('result' not in v for v in self.entries.values())
            return dict(self.metadata, status='ready', serving_queue=self.jobs.qsize(), serving_active=self.active, http_active=self.http_active, pending_joins=pending)
        if path == '/sink':
            content = payload(data['data'])
            return dict(status='ok', bytes=len(content), sha256=digest(content))
        key = identity(data)
        if path == '/infer':
            if self.task == 'fusion':
                inputs = {k: base64.b64decode(data['inputs'][k], validate=True) for k in ('vision', 'speech')}
                argument = inputs
            else:
                argument = payload(data['data'])
                inputs = {'source': argument}
            output, compute, queue = self.invoke(argument, data.get('remaining_s', 120))
            return {'status': 'ok', 'data': base64.b64encode(output).decode(),
                    'receipt': self.receipt(inputs, output, compute, queue)}
        if path == '/execute':
            started = time.monotonic()
            if self.task not in ('vision', 'speech'):
                raise ProtocolError('Only branch operators accept execute')
            content = payload(data['data'])
            output, compute, queue = self.invoke(content, data.get('remaining_s', 120))
            receipt = self.receipt({'source': content}, output, compute, queue)
            remaining = data.get('remaining_s', 120) - (time.monotonic() - started)
            if remaining <= 0:
                raise ProtocolError('Deadline before forwarding', 504)
            request(data['fusion_url'] + '/join', dict(run_id=key[0], request_id=key[1],
                    task=self.task, data=output, receipt=receipt, remaining_s=remaining), timeout=remaining)
            return {'status': 'forwarded', 'receipt': receipt}
        if self.task != 'fusion':
            raise ProtocolError('Only fusion accepts open/join/result')
        execute = None
        with self.lock:
            now = time.monotonic()
            self.entries = {k: v for k, v in self.entries.items() if now - v['created'] <= self.ttl}
            self.tombstones = {k: v for k, v in self.tombstones.items() if now - v <= self.ttl}
            if path == '/open':
                if key in self.entries or key in self.tombstones:
                    raise ProtocolError('Request already registered', 409)
                if sum('result' not in v for v in self.entries.values()) >= self.capacity:
                    raise ProtocolError('Join capacity reached', 429)
                self.entries[key] = {'created': now, 'inputs': {}, 'receipts': {}}
                return {'status': 'registered'}
            if key not in self.entries:
                raise ProtocolError('Unknown or released request', 410)
            item = self.entries[key]
            if path in ('/ack', '/cancel'):
                if path == '/ack' and 'result' not in item:
                    raise ProtocolError('Cannot acknowledge incomplete request', 409)
                del self.entries[key]
                self.tombstones[key] = now
                while len(self.tombstones) > 1024:
                    del self.tombstones[next(iter(self.tombstones))]
                return {'status': 'released'}
            if path == '/result':
                if 'result' not in item:
                    raise ProtocolError('Both branches have not completed', 409)
                return item['result']
            if path != '/join':
                raise ProtocolError('Unknown endpoint', 404)
            task = data['task']
            if task not in ('vision', 'speech'):
                raise ProtocolError('Invalid branch task')
            content = payload(data['data'])
            receipt = data['receipt']
            if receipt.get('task') != task or receipt.get('output_sha256') != digest(content) or receipt.get('output_bytes') != len(content):
                raise ProtocolError('Branch receipt does not match transferred payload')
            if task in item['receipts']:
                if item['receipts'][task] != receipt:
                    raise ProtocolError('Conflicting duplicate branch', 409)
                return {'status': 'duplicate'}
            item['inputs'][task], item['receipts'][task] = content, receipt
            if len(item['inputs']) == 2:
                execute = dict(item['inputs'])
        # Inference and FIFO waiting must never hold the global request-state lock.
        if execute is not None:
            output, compute, waiting = self.invoke(execute, data.get('remaining_s', 120))
            final = self.receipt(execute, output, compute, waiting)
            with self.lock:
                if self.entries.get(key) is not item:
                    raise ProtocolError('Request cancelled during inference', 410)
                item['result'] = {'status': 'ok', 'run_id': key[0], 'request_id': key[1],
                                  'data': base64.b64encode(output).decode(),
                                  'receipts': [item['receipts']['vision'], item['receipts']['speech'], final]}
                item['inputs'].clear()
                completed = [k for k, v in self.entries.items() if 'result' in v]
                for old in completed[:-128]:
                    del self.entries[old]
        return {'status': 'accepted'}


class Handler(BaseHTTPRequestHandler):
    def do_GET(self):
        if self.path != '/health':
            self.send_error(404)
            return
        raw = json.dumps(dict(self.server.metadata, status='ready')).encode()
        self.send_response(200)
        self.send_header('Content-Length', str(len(raw)))
        self.end_headers()
        self.wfile.write(raw)

    def do_POST(self):
        counted = self.path != '/health'
        if counted: self.server.http_active += 1
        try: self._post()
        finally:
            if counted: self.server.http_active -= 1

    def _post(self):
        status = 200
        try:
            size = int(self.headers.get('Content-Length', '0'))
            if size <= 0 or size > 16 * 1024 * 1024:
                raise ProtocolError('Invalid or oversized body', 413)
            data = decode_body(self.rfile.read(size), self.headers.get('Content-Type'))
            result = self.server.operate(self.path, data)
        except ProtocolError as error:
            status, result = error.status, {'status': 'error', 'error': str(error)}
        except (ValueError, TypeError, KeyError) as error:
            status, result = 400, {'status': 'error', 'error': str(error)}
        except Exception as error:
            status, result = 500, {'status': 'error', 'error': repr(error)}
        raw = json.dumps(result, separators=(',', ':')).encode()
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Content-Length', str(len(raw)))
        self.end_headers()
        try:
            self.wfile.write(raw)
        except (BrokenPipeError, ConnectionResetError):
            pass  # Client deadline elapsed; source terminal row records it.

    def log_message(self, *args):
        pass


@contextmanager
def serve(task, adapter, **options):
    server = OperatorServer(('127.0.0.1', 0), task, adapter, **options)
    thread = threading.Thread(target=server.serve_forever, daemon=True)
    thread.start()
    try:
        yield 'http://127.0.0.1:' + str(server.server_port)
    finally:
        server.shutdown()
        server.server_close()
        thread.join()


if __name__ == '__main__':
    import importlib
    module = importlib.import_module(os.environ['ADAPTER_MODULE'])
    task = os.environ['TASK_ID']
    adapter, metadata = module.load(task)
    server = OperatorServer(('0.0.0.0', 8080), task, adapter, metadata)
    print(json.dumps({'event': 'ready', **server.metadata}), flush=True)
    server.serve_forever()
